<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import ZoomViewport from './ZoomViewport.vue';
import {useDraftHistory} from './modules/useDraftHistory';
import ToolIcon from './ToolIcon.vue';
import {mapPiece,moveNode,piecePath,pointBounds} from '../../../packages/pattern/edit';
import {cloneSource,insertSourceNode,removeSourceNode,sourceDrawingIssue,sourceImageTransform,type SourceEdit,type SourceOperation,type SourcePoint} from '../../../packages/reference/source-edit';
import {drawingIssue} from '../../../packages/surface/drawing';
import type {Piece,Reference} from '../../../packages/schema/index';
const props=defineProps<{piece:Piece;reference?:Reference;language:'zh'|'en';busy?:boolean;resetToken?:number;saveError?:string}>(),emit=defineEmits<{commit:[edit:SourceEdit];dirty:[value:boolean]}>(),zh=computed(()=>props.language==='zh');
const editorHeight=ref(360);let sizeDrag:{y:number;height:number}|undefined;
function beginSize(e:PointerEvent){if(e.button!==0)return;e.preventDefault();sizeDrag={y:e.clientY,height:editorHeight.value};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);}
function moveSize(e:PointerEvent){if(sizeDrag)editorHeight.value=Math.max(220,Math.min(1200,sizeDrag.height+e.clientY-sizeDrag.y));}
function saveSize(){sizeDrag=undefined;try{localStorage.setItem('fpcad.source-editor.height',String(editorHeight.value));}catch{}}
onMounted(()=>{try{const h=Number(localStorage.getItem('fpcad.source-editor.height'));if(h>=220&&h<=1200)editorHeight.value=h;}catch{}});
const draft=ref(cloneSource(props.piece)),operations=ref<SourceOperation[]>([]),pen=ref<SourcePoint[]>([]),stroke=ref<SourcePoint[]>([]),tool=ref<'node'|'pan'|'brush-add'|'brush-erase'|'pen-add'|'pen-erase'>('node'),interaction=ref<'edit'|'pan'>('edit'),radius=ref(5),selectedNode=ref(''),selectedPen=ref(-1),showImage=ref(true),expanded=ref(false),message=ref(''),svg=ref<SVGSVGElement>(),size=ref({width:250,height:260}),baseline=ref(JSON.stringify(props.piece));
const dirty=computed(()=>JSON.stringify(draft.value)!==baseline.value||operations.value.length>0||pen.value.length>0||stroke.value.length>0),stale=computed(()=>JSON.stringify(props.piece)!==baseline.value),error=computed(()=>sourceDrawingIssue(draft.value)),penError=computed(()=>drawingIssue(pen.value)),imageTransform=computed(()=>props.reference?sourceImageTransform(props.reference):undefined);
const saveMessage=computed(()=>{if(!props.saveError)return '';const reason=({MARKING_LOCKED:zh.value?'关联贴附已锁定，请解锁后重试。':localize('Unlock the linked placement and retry.'),MANUAL_MARKING_REVIEW:zh.value?'关联贴附含人工编辑，请先核对该贴附。':localize('Review the linked manual placement before changing its source.'),MARKING_SOURCE_BOUND:zh.value?'该源花纹已绑定裁片，请解除绑定后编辑。':localize('Unbind the source from its cut piece before editing.'),MARKING_DISCONNECTED:zh.value?'编辑产生了多个不相连区域，请撤回或调整笔画。':localize('This edit creates separate islands; undo or adjust the strokes.'),EMPTY_MARKING:zh.value?'笔画会擦除全部花纹；取消草稿后可删除来源。':localize('This erases the whole source; cancel the draft to delete it.'),INVALID_GEOMETRY:zh.value?'轮廓或孔洞无效，请修正交叉和重合。':localize('Repair contour or hole crossings and overlaps.'),RESOURCE_LIMIT:zh.value?'编辑复杂度过高，请减少节点或笔画。':localize('Reduce the number of nodes or strokes.'),NO_VISIBLE_PROJECTION:zh.value?'更新后的花纹无法贴附到关联模型，请调整轮廓。':localize('The edited source misses its linked model; adjust the contour.'),STALE_MARKING:zh.value?'关联贴附已失效，请先修复关联。':localize('Repair the stale linked placement first.'),REVISION_CONFLICT:zh.value?'项目已更新，请取消草稿后重新编辑。':localize('The project changed; cancel and reload the draft.'),CONNECTION_ERROR:zh.value?'连接暂不可用，请重试。':localize('Connection unavailable; retry.')} as Record<string,string>)[props.saveError]??(zh.value?'未能保存，请重试或取消。':localize('Save failed; retry or cancel.'));return reason+(zh.value?' 草稿已保留。':localize(' Your draft is retained.'));});
watch(dirty,value=>emit('dirty',value),{immediate:true});
function reset(){history.reset(()=>{draft.value=cloneSource(props.piece);baseline.value=JSON.stringify(props.piece);operations.value=[];pen.value=[];stroke.value=[];selectedNode.value='';selectedPen.value=-1;gesture=undefined;message.value='';});}
watch(()=>props.resetToken,reset);watch(()=>props.piece,p=>{if(!dirty.value)reset();else if(p.id!==draft.value.id)reset();});
const baseBox=ref('');function fitBox(){const b=pointBounds([...props.piece.nodes,...(props.piece.holes??[]).flat(),...(props.piece.curves??[]).flatMap(c=>[c.c1,c.c2])]),pad=Math.max(5,Math.max(b.maxX-b.minX,b.maxY-b.minY)*.3);baseBox.value=`${b.minX-pad} ${-b.maxY-pad} ${b.maxX-b.minX+pad*2} ${b.maxY-b.minY+pad*2}`;}
watch(()=>props.piece.id,fitBox,{immediate:true});
function view(box:string){const [x,y,width,height]=box.split(/\s+/).map(Number);return {x,y,width,height};}
function handleRadius(box:string){const b=view(box);return 5*Math.max(b.width/Math.max(1,size.value.width),b.height/Math.max(1,size.value.height));}
const nodes=computed(()=>[draft.value.nodes,...(draft.value.holes??[])].flat()),selectedPoint=computed(()=>nodes.value.find(n=>n.id===selectedNode.value)),handles=computed(()=>draft.value.curves?.flatMap(c=>[{id:c.c1.id,curveId:c.id,kind:'c1' as const,point:c.c1,anchor:draft.value.nodes.find(n=>n.id===c.startNodeId)!},{id:c.c2.id,curveId:c.id,kind:'c2' as const,point:c.c2,anchor:draft.value.nodes.find(n=>n.id===c.endNodeId)!}])??[]);
const operationMode=computed(()=>tool.value.endsWith('erase')?'erase' as const:'add' as const),operationColor=computed(()=>operationMode.value==='erase'?'var(--danger)':'var(--accent)'),canNodes=computed(()=>!props.busy&&!operations.value.length),canConfirm=computed(()=>dirty.value&&!props.busy&&!stale.value&&!error.value&&!pen.value.length&&!stroke.value.length);
const maskId='source-edit-'+crypto.randomUUID();
function path(points:SourcePoint[],closed=false){return points.map((p,i)=>(i?'L':'M')+p.xMm+','+-p.yMm).join(' ')+(closed?' Z':'');}
function useTool(next:typeof tool.value){if(props.busy||gesture)return;if(next==='node'&&operations.value.length){message.value=zh.value?'先确认笔画，再编辑生成的新节点。':localize('Confirm the strokes before editing the resulting nodes.');return;}tool.value=next;interaction.value=next==='pan'?'pan':'edit';selectedNode.value='';message.value='';}
function setInteraction(value:'pan'|'edit'){interaction.value=value;if(value==='pan')tool.value='pan';else if(tool.value==='pan')tool.value='node';}
function point(event:PointerEvent){const matrix=svg.value?.getScreenCTM();if(!matrix)return;const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());return {xMm:p.x,yMm:-p.y};}
let gesture:{kind:'node';id:string}|{kind:'handle';curveId:string;handle:'c1'|'c2'}|{kind:'translate';start:SourcePoint;original:Piece}|{kind:'brush'}|{kind:'pen';index:number}|undefined,observer:ResizeObserver|undefined;
const history=useDraftHistory(()=>({draft:draft.value,operations:operations.value,pen:pen.value,stroke:stroke.value}),value=>{draft.value=value.draft;operations.value=value.operations;pen.value=value.pen;stroke.value=value.stroke;gesture=undefined;selectedNode.value='';selectedPen.value=-1;},()=>!!svg.value?.getClientRects().length,()=>!!props.busy);
function capture(event:PointerEvent){history.begin();event.preventDefault();svg.value?.setPointerCapture(event.pointerId);}
function startNode(event:PointerEvent,id:string){svg.value?.focus({preventScroll:true});if(event.button!==0||interaction.value==='pan'||!canNodes.value||tool.value!=='node')return;event.stopPropagation();selectedNode.value=id;gesture={kind:'node',id};capture(event);}
function startHandle(event:PointerEvent,curveId:string,handle:'c1'|'c2'){if(event.button!==0||interaction.value==='pan'||!canNodes.value||tool.value!=='node')return;event.stopPropagation();gesture={kind:'handle',curveId,handle};capture(event);}
function startPen(event:PointerEvent,index:number){if(event.button!==0||props.busy||interaction.value==='pan'||!tool.value.startsWith('pen'))return;event.stopPropagation();selectedPen.value=index;gesture={kind:'pen',index};capture(event);}
function down(event:PointerEvent){svg.value?.focus({preventScroll:true});if(event.button!==0||interaction.value==='pan'||props.busy)return;const p=point(event);if(!p)return;if(tool.value==='node'){selectedNode.value='';if(!canNodes.value)return;if(event.ctrlKey||event.metaKey){try{const next=insertSourceNode(draft.value,p);draft.value=next.piece;selectedNode.value=next.nodeId;}catch(e){message.value=(e as Error).message;}return;}if(event.shiftKey){gesture={kind:'translate',start:p,original:cloneSource(draft.value)};capture(event);}return;}
 if(tool.value.startsWith('brush')){if(!Number.isFinite(radius.value)||radius.value<.1||radius.value>200){message.value=zh.value?'笔刷半径须为 0.1–200 mm。':localize('Brush radius must be 0.1–200 mm.');return;}if(operations.value.length>=50){message.value=zh.value?'笔画过多，请先确认。':localize('Confirm these strokes before drawing more.');return;}history.begin();stroke.value=[p];gesture={kind:'brush'};capture(event);return;}
 if(tool.value.startsWith('pen')){if(pen.value.length>=2000){message.value=zh.value?'路径最多 2000 个节点。':localize('At most 2000 path nodes.');return;}pen.value.push(p);selectedPen.value=pen.value.length-1;}
}
function move(event:PointerEvent){if(!gesture||props.busy)return;const p=point(event);if(!p)return;if(gesture.kind==='pen')pen.value[gesture.index]=p;else if(gesture.kind==='node')draft.value=moveNode(draft.value,gesture.id,p.xMm,p.yMm);else if(gesture.kind==='handle'){const {curveId,handle}=gesture;draft.value={...draft.value,curves:draft.value.curves?.map(c=>c.id===curveId?{...c,[handle]:{...c[handle],...p}}:c)};}else if(gesture.kind==='translate'){const {start,original}=gesture;draft.value=mapPiece(original,n=>({xMm:n.xMm+p.xMm-start.xMm,yMm:n.yMm+p.yMm-start.yMm}));}else{const last=stroke.value.at(-1)!;if(Math.hypot(p.xMm-last.xMm,p.yMm-last.yMm)>=Math.max(.05,radius.value/8)){if(stroke.value.length>=500){history.rollback();stroke.value=[];gesture=undefined;message.value=zh.value?'这一笔过长，已取消；请分成较短笔画。':localize('Stroke too long; cancelled. Draw shorter strokes.');}else stroke.value.push(p);}}}
function finish(event:PointerEvent){if(event.type==='pointercancel'){history.rollback();gesture=undefined;return;}if(gesture?.kind==='brush'&&stroke.value.length&&event.type!=='pointercancel')operations.value.push({kind:'brush',mode:operationMode.value,radiusMm:radius.value,points:stroke.value.map(p=>({...p}))});stroke.value=[];gesture=undefined;history.end();}
function closePen(){if(pen.value.length<3||penError.value||operations.value.length>=50)return;history.begin();operations.value.push({kind:'pen',mode:operationMode.value,points:pen.value.map(p=>({...p}))});pen.value=[];selectedPen.value=-1;history.end();}
function remove(){if(!selectedNode.value||!canNodes.value)return;const ring=[draft.value.nodes,...(draft.value.holes??[])].find(r=>r.some(n=>n.id===selectedNode.value));if(ring&&ring.length<=3){message.value=zh.value?'闭合轮廓至少保留 3 个节点。':localize('A closed contour needs at least 3 nodes.');return;}draft.value=removeSourceNode(draft.value,selectedNode.value);selectedNode.value='';}
function curve(){const p=selectedPoint.value;if(!p||!canNodes.value||!draft.value.nodes.some(n=>n.id===p.id))return;const i=draft.value.nodes.findIndex(n=>n.id===p.id),b=draft.value.nodes[(i+1)%draft.value.nodes.length],existing=draft.value.curves?.find(c=>c.startNodeId===p.id),curves=draft.value.curves?.filter(c=>c.startNodeId!==p.id)??[];if(!existing)curves.push({id:crypto.randomUUID(),startNodeId:p.id,endNodeId:b.id,c1:{id:crypto.randomUUID(),xMm:p.xMm+(b.xMm-p.xMm)/3,yMm:p.yMm+(b.yMm-p.yMm)/3},c2:{id:crypto.randomUUID(),xMm:p.xMm+2*(b.xMm-p.xMm)/3,yMm:p.yMm+2*(b.yMm-p.yMm)/3}});draft.value={...draft.value,curves};}
function key(event:KeyboardEvent){if(event.target instanceof Element&&event.target.closest('input,textarea,select,[contenteditable=true]'))return;if((event.ctrlKey||event.metaKey)&&['z','y'].includes(event.key.toLowerCase()))return;if(['Delete','Backspace'].includes(event.key)){event.preventDefault();event.stopPropagation();if(pen.value.length){if(selectedPen.value>=0)pen.value.splice(selectedPen.value,1);else pen.value.pop();selectedPen.value=-1;}else remove();}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(pen.value.length){pen.value=[];return;}if(gesture){history.rollback();stroke.value=[];gesture=undefined;return;}selectedNode.value='';}}
function confirm(){if(!canConfirm.value)return;emit('commit',{piece:cloneSource(draft.value),operations:JSON.parse(JSON.stringify(operations.value)) as SourceOperation[]});}
onMounted(()=>{observer=new ResizeObserver(entries=>{const r=entries[0]?.contentRect;if(r)size.value={width:r.width,height:r.height};});if(svg.value)observer.observe(svg.value);});onBeforeUnmount(()=>observer?.disconnect());
</script>
<template><Teleport to="body" :disabled="!expanded"><section class="source-region-editor" :class="{expanded}" :role="expanded?'dialog':undefined" :aria-modal="expanded?'true':undefined" :aria-label="zh?'源花纹可视编辑':localize('Visual source marking editor')" @keydown="key">
 <header><strong>{{zh?'直接编辑源花纹':localize('Edit source contour')}}</strong><button :aria-label="expanded?(zh?'收起源花纹编辑':localize('Collapse source editor')):(zh?'放大源花纹编辑':localize('Expand source editor'))" @click="expanded=!expanded">{{expanded?'↙':'↗'}}</button></header>
 <div class="source-edit-options"><label v-if="imageTransform"><input v-model="showImage" type="checkbox">{{zh?'显示原图背景':localize('Show original image')}}</label><label v-if="tool.startsWith('brush')">{{zh?'半径 mm':localize('Radius mm')}}<input v-model.number="radius" aria-label="Source brush radius" type="number" min=".1" max="200" step=".5" :disabled="busy"></label><span v-if="operations.length">{{operations.length}} {{zh?'笔待确认':localize('strokes pending')}}</span></div>
 <ZoomViewport :view-box="baseBox" :language="language" label="Source marking" hide-interaction-tools :drawing="!!gesture" :interaction="interaction" @interaction="setInteraction">
  <template #rail><button :class="{active:tool==='node'}" :disabled="busy||!!operations.length" :aria-label="zh?'源花纹节点编辑':localize('Edit source nodes')" :title="zh?'选择节点，Ctrl 点击轮廓插入节点':localize('Select nodes; Ctrl-click a contour to insert')" @click="useTool('node')"><ToolIcon name="select"/></button><button :class="{active:tool==='pan'}" :aria-label="zh?'源花纹平移视图':localize('Pan source view')" @click="useTool('pan')"><ToolIcon name="pan"/></button><button v-for="mode in (['add','erase'] as const)" :key="'brush-'+mode" :class="{active:tool==='brush-'+mode}" :disabled="busy" :aria-label="mode==='add'?(zh?'源花纹笔刷添加':localize('Source brush add')):(zh?'源花纹笔刷擦除':localize('Source brush erase'))" @click="useTool(('brush-'+mode) as typeof tool)"><ToolIcon :name="mode==='add'?'color':'delete'"/></button><button v-for="mode in (['add','erase'] as const)" :key="'pen-'+mode" :class="{active:tool==='pen-'+mode}" :disabled="busy" :aria-label="mode==='add'?(zh?'源花纹钢笔添加':localize('Source pen add')):(zh?'源花纹钢笔减去':localize('Source pen subtract'))" @click="useTool(('pen-'+mode) as typeof tool)"><ToolIcon name="pen"/></button></template>
  <template #default="{viewBox}"><svg ref="svg" class="source-region-preview" tabindex="0" :style="expanded?undefined:{height:editorHeight+'px'}" :viewBox="viewBox" :data-source-id="piece.id" :data-dirty="dirty" :data-node-count="nodes.length" :data-operation-count="operations.length" :aria-label="zh?'源花纹可编辑预览':localize('Editable source marking preview')" @pointerdown="down" @pointermove="move" @pointerup="finish" @pointercancel="finish" @lostpointercapture="gesture=undefined;history.end()">
   <image v-if="showImage&&reference&&imageTransform" class="source-original-image" :href="reference.png" :width="reference.width" :height="reference.height" :transform="imageTransform" opacity=".6"/>
   <defs><mask :id="maskId" maskUnits="userSpaceOnUse" :x="view(viewBox).x" :y="view(viewBox).y" :width="view(viewBox).width" :height="view(viewBox).height"><path :d="piecePath(draft)" fill="white" fill-rule="evenodd"/><template v-for="(op,i) in operations" :key="i"><path v-if="op.kind==='pen'" :d="path(op.points,true)" :fill="op.mode==='add'?'white':'black'"/><path v-else :d="path(op.points.length===1?[op.points[0],{xMm:op.points[0].xMm+.00001,yMm:op.points[0].yMm}]:op.points)" fill="none" :stroke="op.mode==='add'?'white':'black'" :stroke-width="op.radiusMm*2" stroke-linecap="round" stroke-linejoin="round"/></template></mask></defs>
   <rect :x="view(viewBox).x" :y="view(viewBox).y" :width="view(viewBox).width" :height="view(viewBox).height" :fill="draft.color" fill-opacity=".72" :mask="`url(#${maskId})`" pointer-events="none"/>
   <path class="source-contour" :d="piecePath(draft)" fill="none" stroke="var(--accent)" :opacity="operations.length?.35:1" vector-effect="non-scaling-stroke" stroke-width="1.5"/>
   <path v-if="stroke.length" :d="path(stroke.length===1?[stroke[0],{xMm:stroke[0].xMm+.00001,yMm:stroke[0].yMm}]:stroke)" fill="none" :stroke="operationColor" :stroke-width="radius*2" stroke-opacity=".45" stroke-linecap="round" stroke-linejoin="round" pointer-events="none"/>
   <path v-if="pen.length" class="source-pen-draft" :d="path(pen,pen.length>=3)" :fill="operationColor" fill-opacity=".2" :stroke="operationColor" vector-effect="non-scaling-stroke" stroke-width="2" pointer-events="none"/>
   <circle v-for="(p,i) in pen" class="source-pen-node" :data-pen-index="i" :key="'pen-'+i" :cx="p.xMm" :cy="-p.yMm" :r="handleRadius(viewBox)*.65" :fill="operationColor" stroke="var(--panel)" vector-effect="non-scaling-stroke" @pointerdown="startPen($event,i)"/>
   <g v-if="tool==='node'&&!operations.length" class="source-bezier-handles"><g v-for="handle in handles" :key="handle.id"><line :x1="handle.anchor.xMm" :y1="-handle.anchor.yMm" :x2="handle.point.xMm" :y2="-handle.point.yMm" stroke="var(--text-muted)" vector-effect="non-scaling-stroke" stroke-dasharray="3 3"/><rect :data-handle-id="handle.id" :x="handle.point.xMm-handleRadius(viewBox)*.8" :y="-handle.point.yMm-handleRadius(viewBox)*.8" :width="handleRadius(viewBox)*1.6" :height="handleRadius(viewBox)*1.6" fill="var(--panel)" stroke="var(--accent)" vector-effect="non-scaling-stroke" @pointerdown="startHandle($event,handle.curveId,handle.kind)"/></g></g>
   <g v-if="tool==='node'&&!operations.length" class="source-nodes"><circle v-for="node in nodes" :key="node.id" :data-node-id="node.id" :cx="node.xMm" :cy="-node.yMm" :r="handleRadius(viewBox)" :fill="selectedNode===node.id?'var(--accent)':'var(--panel)'" stroke="var(--accent)" vector-effect="non-scaling-stroke" stroke-width="1.5" @pointerdown="startNode($event,node.id)"/></g>
  </svg></template>
 </ZoomViewport><div v-if="!expanded" class="source-size-handle" role="separator" tabindex="0" aria-orientation="horizontal" :aria-label="zh?'调整源花纹画布高度':localize('Resize source canvas height')" :aria-valuenow="editorHeight" aria-valuemin="220" aria-valuemax="1200" @pointerdown="beginSize" @pointermove="moveSize" @pointerup="saveSize" @pointercancel="saveSize" @lostpointercapture="saveSize" @keydown.up.prevent="editorHeight=Math.max(220,editorHeight-30);saveSize()" @keydown.down.prevent="editorHeight=Math.min(1200,editorHeight+30);saveSize()"><span/></div>
 <div class="source-edit-actions"><button v-if="pen.length" :disabled="busy||pen.length<3||!!penError" @click="closePen">{{operationMode==='add'?(zh?'闭合添加路径':localize('Close additive path')):(zh?'闭合减去路径':localize('Close subtractive path'))}}</button><button v-if="pen.length" :disabled="busy" @click="pen.pop()">{{zh?'撤回路径点':localize('Undo path point')}}</button><button v-if="operations.length" :disabled="busy" @click="operations.pop()">{{zh?'撤回最后一笔':localize('Undo last stroke')}}</button><button v-if="selectedPoint" :disabled="!canNodes" @click="curve">{{draft.curves?.some(c=>c.startNodeId===selectedNode)?(zh?'改为直线':localize('Make straight')):(zh?'改为贝塞尔曲线':localize('Make Bézier curve'))}}</button><button v-if="selectedPoint" :disabled="!canNodes" @click="remove">{{zh?'删除选中源节点':localize('Delete selected source node')}}</button><button class="primary" :disabled="!canConfirm" @click="confirm">{{zh?'确认源花纹编辑':localize('Confirm source marking edit')}}</button><button :disabled="busy||!dirty" @click="reset">{{zh?'取消源花纹编辑':localize('Cancel source marking edit')}}</button></div>
 <small class="source-edit-help">{{tool==='node'?(zh?'拖动节点或方形曲线手柄。Ctrl 点击轮廓插点；Delete 删除选中节点。Shift 拖动移动花纹。':localize('Drag nodes or square curve handles. Ctrl-click inserts; Delete removes the selected node. Shift-drag moves the contour.')):(zh?'钢笔点击落点并闭合路径；笔刷按住拖动。蓝色添加，红色减去。确认后同步原图轮廓。':localize('Click and close a pen path, or drag a brush stroke. Blue adds; red subtracts. Confirm to update the original outline.'))}} {{zh?'中键 / 空格拖动平移视图，滚轮缩放。':localize('Middle/Space drag pans; wheel zooms.')}}</small>
 <p v-if="message||error||penError||stale||saveMessage" class="source-edit-message" role="status">{{saveMessage|| (stale?(zh?'源花纹已更新；取消草稿后重新编辑。':localize('The source changed; cancel this draft and reload.')):(message||(error||penError?(zh?'轮廓有交叉或重合，请调整节点后确认。':localize('Contour crosses or overlaps; repair the nodes before confirming.')) :'')))}}</p>
</section></Teleport></template>
